svg.script:

(function() {
  var fm1p2Data = {
    'zone-cervical': {
      title: 'ZONA 1: AXIAL CERVICAL (PESCOÇO)',
      subtitle: 'Fraqueza dos músculos flexores do pescoço',
      clinical: '"Doutor, não consigo erguer a cabeça do travesseiro."',
      finding: 'Paresia de flexores cervicais (grau 3/5 ou menor).',
      pitfall: 'ICC isolada NUNCA afeta a musculatura axial cervical.',
      note: 'Comprometimento axial é marco das miopatias inflamatórias.'
    },
    'zone-escapular': {
      title: 'ZONA 2: PROXIMAL MS (CINTURA ESCAPULAR)',
      subtitle: 'Fraqueza de deltoides, supraespinhal e peitorais',
      clinical: '"Dificuldade para pentear o cabelo ou pegar objetos no alto."',
      finding: 'Incapacidade de abduzir os braços acima de 90° contra gravidade.',
      pitfall: 'Erradamente atribuído a adinamia/astenia geral da insuficiência cardíaca.',
      note: 'A fraqueza é MOTOR-FOCAL PROXIMAL, não mero cansaço sistêmico.'
    },
    'zone-pelvica': {
      title: 'ZONA 3: PROXIMAL MI (CINTURA PÉLVICA / ESCADA)',
      subtitle: 'Fraqueza de iliopsoas, glúteos e quadríceps',
      clinical: '"Custa muito subir degraus de escada ou levantar de cadeiras baixas."',
      finding: 'Sinal de Gowers positivo (escorar-se nas próprias pernas para levantar).',
      pitfall: 'A dispneia aos degraus é por falha do quadríceps + diafragma, não estase.',
      note: 'Dificuldade para levantar da cadeira sem ajuda das mãos = Miopatia Proximal.'
    },
    'chip-pulmao': {
      title: 'CHIP 1: PULMÕES LIMPOS (SEM CONGESTÃO)',
      subtitle: 'Ausculta pulmonar com murmúrio vesicular fisiológico',
      clinical: '"Não há ortopneia verdadeira nem crepitantes nas bases."',
      finding: 'Campos pulmonares limpos, sem estertores crepitantes em maré montante.',
      pitfall: 'Desmonta a tese de Congestão Pulmonar / Edema Agudo de ICC.',
      note: 'A dispneia na miopatia vem da fraqueza diafragmática / parede torácica.'
    },
    'chip-jugular': {
      title: 'CHIP 2: TURGÊNCIA JUGULAR AUSENTE (0/4+)',
      subtitle: 'Pressão Venosa Central (PVC) normal',
      clinical: '"Ausência de ingurgitamento jugular a 45° ou refluxo hepatojugular."',
      finding: 'Veias jugulares planas, sem ondas de estase venosa sistêmica.',
      pitfall: 'Descarta hipertensão atrial direita e descompensação de ICC direita.',
      note: 'Sem turgência jugular = Ausência de congestão sistêmica.'
    },
    'chip-coracao': {
      title: 'CHIP 3: CORAÇÃO SEM B3 OU RITMO DE GALOPE',
      subtitle: 'Precordiogama normal na ausculta cardíaca',
      clinical: '"Bulhas cardíacas normofonéticas em 2 tempos, sem sopros."',
      finding: 'Sem B3 (terceira bulha) ou ritmo de galope ventricular.',
      pitfall: 'A ausência de B3 afasta disfunção sistólica ventricular aguda.',
      note: 'B1 e B2 limpas indicam que a bomba cardíaca não é a causa do cansaço.'
    },
    'chip-edema': {
      title: 'CHIP 4: MEMBROS INFERIORES SEM EDEMA',
      subtitle: 'Perfusão e drenagem venosa preservadas',
      clinical: '"Ausência de inchaço nos tornozelos ou sinal do cacifo/Godet."',
      finding: 'Membros inferiores sem edema assimétrico ou simétrico (Cacifo 0/4+).',
      pitfall: 'Afasta retenção hidrossalina de origem renal, hepática ou cardíaca.',
      note: 'A dificuldade de andar decorre de miopatia pélvica, não de edema pesado.'
    }
  };

  window.fm1p2Select = function(id) {
    // Clear active class from interactive elements
    var items = document.querySelectorAll('.fm1p2-interactive');
    for (var i = 0; i < items.length; i++) {
      items[i].classList.remove('fm1p2-active');
    }

    // Set active class on target item
    var target = document.getElementById('fm1p2-item-' + id);
    if (target) {
      target.classList.add('fm1p2-active');
    }

    // Update Reading Panel text
    var info = fm1p2Data[id];
    if (info) {
      document.getElementById('fm1p2-panel-title').textContent = info.title;
      document.getElementById('fm1p2-panel-subtitle').textContent = info.subtitle;
      document.getElementById('fm1p2-panel-clinical').textContent = info.clinical;
      document.getElementById('fm1p2-panel-finding').textContent = info.finding;
      document.getElementById('fm1p2-panel-pitfall').textContent = info.pitfall;
      document.getElementById('fm1p2-panel-note').textContent = info.note;
    }
  };

  window.fm1p2SetTab = function(tabName) {
    var tabs = ['all', 'weakness', 'congestion'];
    for (var i = 0; i < tabs.length; i++) {
      var t = document.getElementById('fm1p2-tab-' + tabs[i]);
      if (t) t.classList.remove('fm1p2-tab-active');
    }
    var activeTab = document.getElementById('fm1p2-tab-' + tabName);
    if (activeTab) activeTab.classList.add('fm1p2-tab-active');

    if (tabName === 'weakness') {
      fm1p2Select('zone-cervical');
    } else if (tabName === 'congestion') {
      fm1p2Select('chip-pulmao');
    } else {
      fm1p2Select('zone-cervical');
    }
  };

  // Initialize default view
  fm1p2Select('zone-cervical');
})();
